# =============================================================================
# core/state.py — Shared State (Phase 2 — Universal Version)
#
# LEARNING NOTE — What changed from Phase 1?
#
# Phase 1 state was hardcoded for the refund agent. Phase 2 state now
# carries the DYNAMIC domain model and attack plan generated by the
# Phase A intelligence agents. The chaos attacker, evaluator, and
# synthesizer all read from domain_model and attack_categories instead
# of hardcoded config — this is what makes the system work for ANY
# uploaded codebase, not just the refund bot.
# =============================================================================

from typing import TypedDict


class ShadowOpsState(TypedDict):
    # -------------------------------------------------------------------
    # Set at startup from Project Knowledge Base (Phase A output)
    # -------------------------------------------------------------------

    project_id: str
    target_name: str
    target_code: str          # combined source of agent files, for attacker/synthesizer context

    domain_model: dict        # from code_intelligence.analyse_codebase()
    attack_categories: list   # from attack_planner.plan_attacks()

    # -------------------------------------------------------------------
    # Docker execution context
    # -------------------------------------------------------------------

    container_id: str
    container_endpoint: str

    # -------------------------------------------------------------------
    # Written by Chaos Attacker
    # -------------------------------------------------------------------

    chaos_input: str
    chaos_payload: dict        # structured payload sent to the agent's API
    attack_category: str

    # -------------------------------------------------------------------
    # Written by Docker Executor / target run step
    # -------------------------------------------------------------------

    execution_logs: dict

    # -------------------------------------------------------------------
    # Written by Evaluator
    # -------------------------------------------------------------------

    root_cause: str
    bug_type: str
    severity: str

    # -------------------------------------------------------------------
    # Written by Synthesizer
    # -------------------------------------------------------------------

    proposed_patch: str

    # -------------------------------------------------------------------
    # Control fields
    # -------------------------------------------------------------------

    iteration_count: int
    status: str
    vulnerabilities_found: list
    attacks_launched: int
    total_cost: float


def get_initial_state(project_id: str, target_name: str, target_code: str,
                      domain_model: dict, attack_categories: list,
                      container_id: str = "", container_endpoint: str = "") -> ShadowOpsState:
    """
    Returns a fresh state dictionary, initialised with the domain model
    and attack plan from Phase A (intelligence agents).
    """
    return ShadowOpsState(
        project_id=project_id,
        target_name=target_name,
        target_code=target_code,
        domain_model=domain_model,
        attack_categories=attack_categories,
        container_id=container_id,
        container_endpoint=container_endpoint,
        chaos_input="",
        chaos_payload={},
        attack_category="",
        execution_logs={},
        root_cause="",
        bug_type="",
        severity="",
        proposed_patch="",
        iteration_count=0,
        status="running",
        vulnerabilities_found=[],
        attacks_launched=0,
        total_cost=0.0,
    )
